     }

     h1 {
       margin: 0;
       font-size: clamp(2.5rem, 5vw, 4.5rem);
       line-height: 0.95;
       letter-spacing: -0.05em;
       max-width: 12ch;
     }

     .lead {
       margin: 1rem 0 0;
       max-width: 58ch;
       color: var(--muted);
       font-size: 1.0625rem;
     }

     .hero-card {
       align-self: stretch;
       background: linear-gradient(180deg, #ffffff, #f8faff);
       border: 1px solid var(--border);
       border-radius: var(--radius);
       box-shadow: var(--shadow);
       padding: 1.25rem;
       display: grid;
       gap: 1rem;
     }

     .hero-card h2 {
       margin: 0;
       font-size: 1rem;
     }

     .hero-card ul {
       margin: 0;
       padding: 0;
       list-style: none;
       display: grid;
       gap: 0.75rem;
     }

     .hero-card li {
       padding: 0.8rem 0.9rem;
       border: 1px solid var(--border);
       border-radius: 16px;
       background: var(--surface);
     }

     .hero-card strong {
       display: block;
       margin-bottom: 0.15rem;
     }

     .faq-grid {
       display: grid;
       gap: 1rem;
     }

     .example {
       background: var(--surface);
       border: 1px solid var(--border);
       border-radius: var(--radius);
       box-shadow: var(--shadow);
       overflow: hidden;
     }

     details {
       display: block;
     }

     summary {
       list-style: none;
       cursor: pointer;
       display: flex;
       align-items: center;
       justify-content: space-between;
       gap: 1rem;
       padding: 1.15rem 1.25rem;
       font-size: 1.05rem;
       font-weight: 700;
       color: var(--text);
     }

     summary::-webkit-details-marker {
       display: none;
     }

     summary:focus-visible {
       outline: 3px solid var(--accent);
       outline-offset: -3px;
     }

     .question {
       display: flex;
       align-items: center;
       gap: 0.75rem;
       min-width: 0;
     }

     .badge {
       flex: none;
       display: inline-flex;
       align-items: center;
       justify-content: center;
       width: 2rem;
       height: 2rem;
       border-radius: 999px;
       background: var(--surface-alt);
       color: var(--accent-strong);
       font-size: 0.875rem;
       font-weight: 800;
     }

     .summary-text {
       min-width: 0;
       overflow-wrap: anywhere;
     }

     .chevron {
       flex: none;
       width: 0.8rem;
       height: 0.8rem;
       border-right: 2px solid currentColor;
       border-bottom: 2px solid currentColor;
       transform: rotate(45deg);
       transition: transform 0.2s ease;
     }

     details[open] .chevron {
       transform: rotate(225deg);
     }

     .details {
       padding: 0 1.25rem 1.25rem;
       color: var(--muted);
       overflow-wrap: anywhere;
     }

     .details p {
       margin: 0;
       max-width: 70ch;
     }

     .details p + p {
       margin-top: 0.85rem;
     }

     footer {
       padding: 2rem 0 0;
       color: var(--muted);
       font-size: 0.95rem;
     }

     @media (max-width: 760px) {
       .page {
         width: min(100% - 1rem, 1120px);
         padding-top: 3.5rem;
       }

       .hero {
         grid-template-columns: 1fr;
       }

       h1 {
         max-width: 100%;
       }
     }

